def islands_after_each(rows: int, cols: int, cells: list[list[int]]) -> list[int]:
    land, counts = set(), []
    for r, c in cells:
        land.add((r, c))
        seen, islands = set(), 0
        for start in land:                   # recount the whole map after every addition
            if start in seen:
                continue
            islands += 1
            seen.add(start)
            stack = [start]
            while stack:
                x, y = stack.pop()
                for nxt in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if nxt in land and nxt not in seen:
                        seen.add(nxt)
                        stack.append(nxt)
        counts.append(islands)
    return counts
